"use client"

import * as React from "react"
import { AnimatePresence, LayoutGroup, motion, useReducedMotion } from "motion/react"
import { Check, Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { motionPresets } from "@/lib/motion"
import { SegmentedControl } from "@/components/ui/segmented-control"

export type ViewOption = {
  id: string
  label: string
  icon?: React.ReactNode
}

export type ViewCustomizerClassNames = {
  content?: string
  tile?: string
  footer?: string
}

export type ViewCustomizerProps = {
  title?: string
  subtitle?: string
  views: readonly ViewOption[]
  enabled: readonly string[]
  onEnabledChange: (ids: string[]) => void
  showAllLabel?: string
  /** At least one view stays enabled. */
  minimumLabel?: string
  footer?: React.ReactNode
  children: React.ReactNode
  className?: string
  classNames?: ViewCustomizerClassNames
}

export function ViewCustomizer({
  title = "Views",
  subtitle,
  views,
  enabled,
  onEnabledChange,
  showAllLabel = "Show all",
  minimumLabel = "At least one view stays on.",
  footer,
  children,
  className,
  classNames,
}: ViewCustomizerProps) {
  const enabledSet = new Set(enabled)
  const allOn = views.length > 0 && views.every((view) => enabledSet.has(view.id))
  const [notice, setNotice] = React.useState("")

  function toggle(id: string) {
    const on = enabledSet.has(id)
    if (on && enabled.length <= 1) {
      setNotice(minimumLabel)
      return
    }
    setNotice("")
    const next = on ? enabled.filter((item) => item !== id) : [...enabled, id]
    onEnabledChange(views.map((view) => view.id).filter((item) => next.includes(item)))
  }

  return (
    <Popover>
      <PopoverTrigger asChild>{children}</PopoverTrigger>
      <PopoverContent
        side="top"
        sideOffset={12}
        className={cn("relative w-80 gap-3 p-3", className, classNames?.content)}
      >
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <h2 className="text-sm font-semibold">{title}</h2>
            {subtitle ? <p className="mt-0.5 text-xs text-muted-foreground wrap-anywhere">{subtitle}</p> : null}
          </div>
          {allOn ? null : (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="shrink-0"
              onClick={() => {
                setNotice("")
                onEnabledChange(views.map((view) => view.id))
              }}
            >
              {showAllLabel}
            </Button>
          )}
        </div>
        <div role="group" aria-label={title} className="grid grid-cols-4 gap-2">
          {views.map((view) => {
            const on = enabledSet.has(view.id)
            return (
              <button
                key={view.id}
                type="button"
                aria-pressed={on}
                className={cn(
                  "relative flex min-h-16 flex-col items-center justify-center gap-1 rounded-lg px-1 py-2 text-xs focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                  on
                    ? "border border-border bg-muted font-semibold text-foreground"
                    : "border border-dashed border-border bg-transparent text-muted-foreground",
                  "hover:bg-accent hover:text-accent-foreground",
                  classNames?.tile,
                )}
                onClick={() => toggle(view.id)}
              >
                {on ? (
                  <span className="absolute -top-1 -end-1 grid size-4 place-items-center rounded-full bg-primary text-primary-foreground">
                    <Check className="size-2.5" aria-hidden />
                  </span>
                ) : null}
                {view.icon ? <span aria-hidden>{view.icon}</span> : null}
                <span className="max-w-full truncate">{view.label}</span>
              </button>
            )
          })}
        </div>
        <p className="sr-only" role="status">
          {notice}
        </p>
        {footer ? <div className={cn("border-t border-border pt-2 text-xs text-muted-foreground", classNames?.footer)}>{footer}</div> : null}
        <span
          aria-hidden
          className="absolute top-full left-1/2 size-2 -translate-x-1/2 -translate-y-1/2 rotate-45 border-r border-b border-border bg-popover"
        />
      </PopoverContent>
    </Popover>
  )
}

export type ViewSwitcherItem = {
  id: string
  label: string
  icon?: React.ReactNode
}

export type ViewSwitcherProps = {
  views: readonly ViewSwitcherItem[]
  value?: string
  onValueChange?: (id: string) => void
  onAdd?: () => void
  addLabel?: string
  label?: string
  /** The views menu, usually the "…" trigger for `ViewCustomizer`. */
  menu?: React.ReactNode
  className?: string
}

export function ViewSwitcher({
  views,
  value,
  onValueChange,
  onAdd,
  addLabel = "Add",
  label = "Views",
  menu,
  className,
}: ViewSwitcherProps) {
  const reduced = useReducedMotion()
  const showPill = views.length >= 2
  const spring = reduced ? { duration: 0 } : motionPresets.spring.snappy
  const selected = value && views.some((view) => view.id === value) ? value : views[0]?.id

  return (
    <LayoutGroup>
      <div data-slot="view-switcher" className={cn("inline-flex items-center gap-1.5", className)}>
        {onAdd ? (
          <motion.div layout="position" transition={spring}>
            <Button
              type="button"
              variant="outline"
              size="icon"
              className="rounded-full"
              aria-label={addLabel}
              onClick={onAdd}
            >
              <Plus />
            </Button>
          </motion.div>
        ) : null}
        <AnimatePresence initial={false}>
          {showPill && selected ? (
            <motion.div
              key="view-switcher-pill"
              data-slot="view-switcher-pill"
              layout
              initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.92 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.92 }}
              transition={spring}
            >
              <SegmentedControl
                label={label}
                iconsOnly
                value={selected}
                onValueChange={onValueChange}
                options={views.map((view) => ({
                  value: view.id,
                  label: view.label,
                  icon: view.icon,
                }))}
                classNames={{
                  track: "rounded-full",
                  option: "rounded-full px-2.5",
                  selection: "rounded-full",
                }}
              />
            </motion.div>
          ) : null}
        </AnimatePresence>
        {menu ? (
          <motion.div layout="position" transition={spring}>
            {menu}
          </motion.div>
        ) : null}
      </div>
    </LayoutGroup>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { LayoutGroup, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type Segment = {
  value: string
  label: string
  accessory?: React.ReactNode
  /** Drawn before the label. With `iconsOnly`, the label stays available to assistive tech. */
  icon?: React.ReactNode
}

export type SegmentedControlClassNames = {
  root?: string
  track?: string
  option?: string
  selection?: string
  label?: string
}

export type SegmentedControlProps = {
  options: Segment[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  label?: string
  onOptionIntent?: (value: string) => void
  /** Hides each label visually and keeps it in the accessible name. */
  iconsOnly?: boolean
  className?: string
  classNames?: SegmentedControlClassNames
}

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  onOptionIntent,
  iconsOnly = false,
  className,
  classNames,
}: SegmentedControlProps) {
  const id = React.useId()
  const reduced = useReducedMotion()
  const track = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "")
  const selected = value ?? internal

  React.useLayoutEffect(() => {
    const node = track.current
    if (!node) return
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1)
      node.toggleAttribute("data-fade-end", rest > 1)
    }
    edges()
    node.addEventListener("scroll", edges, { passive: true })
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges)
    observer?.observe(node)
    return () => {
      node.removeEventListener("scroll", edges)
      observer?.disconnect()
    }
  }, [options.length])

  const first = React.useRef(true)
  React.useEffect(() => {
    const node = track.current
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]')
    if (!node || !button || node.scrollWidth <= node.clientWidth) {
      first.current = false
      return
    }
    const room = 20
    const start = button.offsetLeft - room
    const end = button.offsetLeft + button.offsetWidth + room - node.clientWidth
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" })
    first.current = false
  }, [selected, reduced])

  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === selected))

  function change(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const last = options.length - 1
    const target =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? selectedIndex === last
          ? 0
          : selectedIndex + 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? selectedIndex === 0
            ? last
            : selectedIndex - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (target < 0 || !options[target]) return
    event.preventDefault()
    change(options[target].value)
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true })
  }

  return (
    <div
      data-slot="segmented-control"
      className={cn("inline-flex min-w-0 max-w-full shrink", className, classNames?.root)}
      role="group"
      aria-label={label}
    >
      <LayoutGroup id={id}>
        <motion.div
          ref={track}
          layoutScroll
          data-slot="segmented-control-track"
          className={cn(
            "flex min-w-0 gap-0.5 overflow-x-auto rounded-lg bg-muted p-0.5 [scrollbar-width:none]",
            classNames?.track,
          )}
        >
          {options.map((option, index) => {
            const pressed = selected === option.value
            return (
              <button
                key={option.value}
                id={`${id}-${option.value}`}
                type="button"
                data-slot="segmented-control-option"
                data-value={option.value}
                className={cn(
                  "relative min-h-8 shrink-0 cursor-pointer rounded-md border-0 bg-transparent px-3 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none aria-pressed:text-foreground",
                  classNames?.option,
                )}
                aria-pressed={pressed}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => change(option.value)}
                onKeyDown={onKeyDown}
                onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
                onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
              >
                {pressed ? (
                  <motion.span
                    data-slot="segmented-control-selection"
                    className={cn("absolute inset-0 z-0 rounded-md border border-border bg-background shadow-sm", classNames?.selection)}
                    layoutId="selection"
                    layoutDependency={selected}
                    transition={reduced ? { duration: 0 } : motionPresets.spring.morph}
                    aria-hidden="true"
                  />
                ) : null}
                <span data-slot="segmented-control-label" className={cn("relative z-10 inline-flex items-center gap-1.5", classNames?.label)}>
                  {option.icon}
                  {iconsOnly ? <span className="sr-only">{option.label}</span> : option.label}
                  {option.accessory}
                </span>
              </button>
            )
          })}
        </motion.div>
      </LayoutGroup>
    </div>
  )
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    exit: [0.7, 0, 0.84, 0] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
